update orders
cancel_reason=#{cancelReason}, rejection_reason=#{rejectionReason}, cancel_time=#{cancelTime}, pay_status=#{payStatus}, pay_method=#{payMethod}, checkout_time=#{checkoutTime}, status = #{status}, pickup_no=#{pickupNo}, pickup_appointment_time=#{pickupAppointmentTime}, delivery_time = #{deliveryTime}
where id = #{id}

mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id=#{userId}


        and status=#{status}


        and order_time=#{orderTime}


        and end_time=#PendTime}


order by order_time desc

select sum(amount) from orders



        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}

select count(*) from orders



        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}

select order_detail.name,sum(order_detail.number) number
from orders,order_detail
where order_detail.order_id=orders.id

    and orders.status = #{status}


    and orders.order_time > #{begin}


    and orders.order_time < #{end}

group by order_detail.name
order by number desc
limit 0,10
